#include <stdio.h>
int main(){
    double age=3, mileage=40, b=5;
    double ridge_w_age=2.3, ridge_w_mileage=0.8;
    double lasso_w_age=2.1, lasso_w_mileage=0.0;
    double ridge_pred = b + ridge_w_age*age + ridge_w_mileage*mileage;
    double lasso_pred = b + lasso_w_age*age + lasso_w_mileage*mileage;
    printf("%g\n%g\n", ridge_pred, lasso_pred);
    return 0;
}
